/* Exactly one 16x16 native tile copy. Frame-specific content (actors,
   water movement, lights) is layered separately at fixed world anchors. */
void hd_world_tile_art(uint8_t *frame,int sx,int sy,char tile,int wx,int wy){
 unsigned id;
 unsigned variant=(unsigned)((wx*13+wy*7+(wx^wy)*3)&3);
 switch(tile){
 case '#':case 'A': id=14u+((wx+wy)&1?1u:0u);break;
 case ',':case '=':id=4u+variant;break;
 case 'g':case 'T':id=8u+(variant%3u);break;
 case '~':id=11u+(variant%3u);break;
 case 'D':id=18u;break;
 case 'L':id=21u;break;
 default:id=variant;break;
 }
 const uint8_t *src=tile_pixels[id];
 if(sx>=0 && sx+16<=HD_W && sy>=0 && sy+16<=HD_H){
  for(int y=0;y<16;y++)memcpy(frame+(sy+y)*HD_W+sx,src+y*16,16);
 }else{
  for(int y=0;y<16;y++){
   int yy=sy+y;
   if((unsigned)yy>=HD_H)continue;
   for(int x=0;x<16;x++){
    int xx=sx+x;
    if((unsigned)xx<HD_W)frame[yy*HD_W+xx]=src[y*16+x];
   }
  }
 }
}
/* One visually coherent pose per direction and subtle gait phase. Actor
   is guaranteed rooted to (x,foot_y), even while walking/camera pans. */
void hd_world_person_art(uint8_t *dst,int center_x,int foot_y,unsigned role,
                         unsigned facing,unsigned gait){
 const uint8_t *src=person_pixels[((role%7u)*4u+(facing&3u))*2u+(gait&1u)];
 int left=center_x-PERSON_W/2,top=foot_y-32;
 /* Clip the sprite rectangle once. The ARM/IWRAM paint loop then only
    tests the original transparent key; ROM art and foot anchors stay
    byte-identical, including clipped corners and unaligned canvases. */
 int x0=left<0?-left:0,y0=top<0?-top:0;
 int x1=left+PERSON_W>HD_W?HD_W-left:PERSON_W;
 int y1=top+PERSON_H>HD_H?HD_H-top:PERSON_H;
 if(x0>=x1||y0>=y1)return;
 unsigned width=(unsigned)(x1-x0),height=(unsigned)(y1-y0);
 src+=y0*PERSON_W+x0;
 dst+=(top+y0)*HD_W+left+x0;
 for(unsigned y=0;y<height;y++){
  const uint8_t *line=src+y*PERSON_W;
  uint8_t *out=dst+y*HD_W;
  for(unsigned x=0;x<width;x++){
   unsigned ink=line[x];
   if(ink<64u)out[x]=(uint8_t)ink;
  }
 }
}
void hd_world_tree_art(uint8_t *dst,int center_x,int foot_y,unsigned kind,unsigned phase){
 const uint8_t *src=tree_pixels[(kind%3u)*2u+(phase&1u)];
 int left=center_x-TREE_W/2,top=foot_y-36;
 int x0=left<0?-left:0,y0=top<0?-top:0;
 int x1=left+TREE_W>HD_W?HD_W-left:TREE_W;
 int y1=top+TREE_H>HD_H?HD_H-top:TREE_H;
 if(x0>=x1||y0>=y1)return;
 unsigned width=(unsigned)(x1-x0),height=(unsigned)(y1-y0);
 src+=y0*TREE_W+x0;
 dst+=(top+y0)*HD_W+left+x0;
 for(unsigned y=0;y<height;y++){
  const uint8_t *line=src+y*TREE_W;
  uint8_t *out=dst+y*HD_W;
  for(unsigned x=0;x<width;x++){
   unsigned ink=line[x];
   if(ink<64u)out[x]=(uint8_t)ink;
  }
 }
}

/* Perspective scales exactly the ROM sprite artwork for each distance:
   no head/coat proportion drift between 2D and first-person.
   Scale mapping is calculated per COLUMN, not per displayed pixel. */
void hd_world_person_projected(uint8_t *dst,int center_x,int foot_y,int height,
                               unsigned role,unsigned facing,unsigned gait){
 if(height<5)return;
 if(height>116)height=116;
 int width=(height*PERSON_W+PERSON_H/2)/PERSON_H;
 if(width<3)width=3;
 if(width>78)width=78;
 const uint8_t *src=person_pixels[((role%7u)*4u+(facing&3u))*2u+(gait&1u)];
 int left=center_x-width/2,top=foot_y-height;
 uint8_t xmap[78];
 for(int x=0;x<width;x++)xmap[x]=(uint8_t)((x*PERSON_W)/width);
 for(int y=0;y<height;y++){
  int yy=top+y;
  if((unsigned)yy>=HD_H)continue;
  unsigned sy=(unsigned)(y*PERSON_H/height);
  const uint8_t *line=src+sy*PERSON_W;
  uint8_t *out=dst+yy*HD_W;
  for(int x=0;x<width;x++){
   int xx=left+x;
   if((unsigned)xx>=HD_W)continue;
   unsigned ink=line[xmap[x]];
   if(ink<64u)out[xx]=(uint8_t)ink;
  }
 }
}
